pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(uint256 burnAmount, address other) internal {
        vm.assume(other != address(0));
        address owner;
        try c.owner() returns (address __r) { owner = __r; } catch { return; }
        uint256 beforeTotal;
        try c.totalSupply() returns (uint256 __r) { beforeTotal = __r; } catch { return; }
        uint256 ownerBalBefore;
        try c.balanceOf(owner) returns (uint256 __r) { ownerBalBefore = __r; } catch { return; }
        bool nonOwnerReverted;
        try c.burn(burnAmount) {
            nonOwnerReverted = false;
        } catch {
            nonOwnerReverted = true;
        }
        uint256 afterTotal;
        try c.totalSupply() returns (uint256 __r) { afterTotal = __r; } catch { return; }
        uint256 ownerBalAfter;
        try c.balanceOf(owner) returns (uint256 __r) { ownerBalAfter = __r; } catch { return; }
        assertTrue(nonOwnerReverted || (afterTotal + burnAmount == beforeTotal && ownerBalAfter + burnAmount == ownerBalBefore));
    }

    function testFuzz_run(uint256 burnAmount, address other) public {
        vm.assume(other.code.length == 0 && uint160(other) > 0xffff && other != address(this) && other != address(c) && other != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && other != 0x000000000000000000636F6e736F6c652e6c6f67 && other != 0x4e59b44847b379578588920cA78FbF26c0B4956C && other != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(burnAmount, other);
    }

    receive() external payable { }
}
